 ld={'@context':'https://schema.org','@type':'WebPage','name':title,'description':desc,'url':canonical,'dateModified':DATE,'isPartOf':{'@type':'WebSite','name':BRANDS[K][0]+' | '+N[0],'url':URL},'about':{'@type':'Thing','name':'San Jose culture, food, and consumer life'}}
