 html=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{esc(title)} | {BRANDS[K][0]} · {N[0]}</title><meta name="description" content="{esc(desc,quote=True)}"><link rel="canonical" href="{canonical}"><meta property="og:title" content="{BRANDS[K][0]} · {esc(title,quote=True)}"><meta property="og:description" content="{esc(desc,quote=True)}"><meta property="og:type" content="website"><meta property="og:url" content="{canonical}"><meta name="theme-color" content="{("#ef4d2f" if K=="atlas" else "#d0ef46" if K=="terpenes" else "#2457ce")}"><link rel="icon" href="{favicon}"><link rel="stylesheet" href="assets/style.css"><link rel="stylesheet" href="assets/identity.css"><link rel="stylesheet" href="assets/publication.css"><link rel="alternate" type="application/rss+xml" title="{BRANDS[K][0]} journal" href="journal.xml"><script src="assets/publication.js" defer></script><script type="application/ld+json">{json.dumps(ld).replace('</','<\\/')}</script></head><body class="{K}"><a class="sr-only" href="#main">Skip to content</a><header class="top"><div class="nav wrap">{mark()}<nav class="navlinks" aria-label="Main navigation">{''.join(f'<a href="{u}" class="'+('active' if active==u else '')+f'">{t}</a>' for u,t in nav)}<span class="age">21+</span></nav></div></header><main id="main">{body}</main><footer class="footer"><div class="wrap"><div class="footer-top">{mark()}<div class="footer-links"><a href="about.html">About</a><a href="team.html">Our writers</a><a href="editorial-standards.html">Standards</a> <a href="updates.html">Update log</a><a href="advertise.html">Advertise</a><a href="sources.html">Sources & updates</a><a href="privacy.html">Privacy</a></div></div><p>A reference for adults 21+. Educational information, not medical advice. No products are sold on this site. Product names and trademarks belong to their respective owners.</p><p>Published data checked {DATE}. Product availability and checkout terms can change between monthly updates.</p></div></footer><div class="compare-bar" id="compare-bar" hidden><span id="compare-count">0 selected</span><button id="compare-open">Compare</button><button class="clear" id="compare-clear">Clear</button></div><dialog id="compare-dialog"><div class="dialog-top"><div><p class="eyebrow">Side by side</p><h2>Your comparison</h2></div><button class="close" id="compare-close" aria-label="Close comparison">×</button></div><div id="compare-content" class="table-scroll"></div></dialog><script id="site-data" type="application/json">{jsdata}</script><script src="assets/app.js" defer></script><script src="assets/experience.js" defer></script><script src="assets/editorial.js" defer></script></body></html>'''
